(function () {
  if (window.__chooseR1) return;
  var IMG = {"ch_ichi": "data:image/png;base64,", "ch_ni": "data:image/png;base64,", "ch_tag": "data:image/png;base64,", "ch_tab": "data:image/png;base64,", "ch_glow": "data:image/png;base64,", "ch_fight": "data:image/png;base64,"};

  var T = window.__chooseR1 = { v: "ch-r1", built: 0, ready: 0, made: 0, err: "" };
  T.report = function () {
    return { v: T.v, built: T.built, ready: T.ready, made: T.made, err: T.err };
  };

  var IM = {}, SF = {}, loaded = 0, total = 0, k;
  for (k in IMG) total++;
  for (k in IMG) {
    (function (nm) {
      var im = new Image();
      im.onload = function () { loaded++; if (loaded >= total) T.ready = 1; };
      im.onerror = function () { loaded++; if (loaded >= total) T.ready = 1; };
      im.src = IMG[nm];
      IM[nm] = im;
    })(k);
  }

  var INSET = { ch_tab: 26, ch_tag: 20 };

  function frame(nm) {
    if (SF[nm]) return SF[nm];
    var im = IM[nm];
    if (!im || !im.width) return null;
    try {
      var tex = new cc.Texture2D();
      tex.initWithElement(im);
      tex.handleLoadedTexture();
      var sf = new cc.SpriteFrame();
      sf.setTexture(tex);
      sf.setRect(cc.rect(0, 0, im.width, im.height));
      sf.setOriginalSize(cc.size(im.width, im.height));
      if (INSET[nm]) {
        var v = INSET[nm];
        sf.insetLeft = v; sf.insetTop = v; sf.insetRight = v; sf.insetBottom = v;
      }
      sf.name = nm;
      SF[nm] = sf;
      return sf;
    } catch (e) {
      T.err = "frame:" + nm + ":" + (e && e.message);
      return null;
    }
  }

  function mk(parent, name, nm, w, h, opt) {
    opt = opt || {};
    var n = new cc.Node(name);
    var sp = n.addComponent(cc.Sprite);
    if (nm) {
      var sf = frame(nm);
      if (sf) sp.spriteFrame = sf;
    }
    sp.sizeMode = cc.Sprite.SizeMode.CUSTOM;
    if (opt.sliced) sp.type = cc.Sprite.Type.SLICED;
    else sp.type = cc.Sprite.Type.SIMPLE;
    n.setContentSize(w, h);
    if (opt.color) n.color = new cc.Color(opt.color[0], opt.color[1], opt.color[2]);
    if (opt.opacity != null) n.opacity = opt.opacity;
    n.parent = parent;
    if (opt.z != null) n.zIndex = opt.z;
    T.made++;
    return n;
  }

  function need(parent, name, nm, w, h, opt) {
    var n = parent.getChildByName(name);
    if (!n || !n.isValid) n = mk(parent, name, nm, w, h, opt);
    return n;
  }

  /* 屏幕坐标（960x540）转世界：世界 x = 屏 x*2，世界 y = 1080 - 屏 y*2 */
  function wpos(sx, sy) { return cc.v2(sx * 2, 1080 - sy * 2); }
  function place(n, sx, sy) {
    if (!n || !n.parent) return;
    var p = n.parent.convertToNodeSpaceAR(wpos(sx, sy));
    n.setPosition(p.x, p.y);
  }
  function scaleOf(n) {
    var s = 1, p = n;
    while (p) { s *= (p.scaleX || 1); p = p.parent; }
    return s || 1;
  }
  function setS(n, sw, sh) {
    if (!n) return;
    var s = scaleOf(n);
    n.setContentSize(sw * 2 / s, sh * 2 / s);
  }
  function setF(n, px) {
    var l = n && n.getComponent(cc.Label);
    if (!l) return;
    l.fontSize = px * 2 / scaleOf(n);
  }

  function layer(cv, name, before) {
    var n = cv.getChildByName(name);
    if (!n || !n.isValid) {
      n = new cc.Node(name);
      n.parent = cv;
      if (before) {
        var idx = cv.children.indexOf(before);
        if (idx >= 0) n.setSiblingIndex(idx);
      }
      T.made++;
    }
    return n;
  }

  var CV = null, last = 0;

  function build(cv) {
    var bg = cv.getChildByName("bg");
    var bsp = bg && bg.getComponent(cc.Sprite);
    var baseSF = bsp && bsp.spriteFrame;
    if (!baseSF) { T.err = "no bg frame"; return; }

    var tp0 = cv.getChildByName("TopPanel");
    if (tp0) {
      var tsp = tp0.getComponent(cc.Sprite);
      if (tsp) tsp.enabled = false;
    }

    var bgL = layer(cv, "__chBg", cv.getChildByName("blockBg"));
    var topL = layer(cv, "__chTop", cv.getChildByName("TopPanel"));

    /* ---------- 1. 左右分区 ---------- */
    var L = need(bgL, "splitL", null, 1200, 1350, {});
    var lsp = L.getComponent(cc.Sprite);
    if (lsp && !lsp.spriteFrame) lsp.spriteFrame = baseSF;
    L.setContentSize(1200, 1350);
    L.setPosition(-600, 0);
    L.color = new cc.Color(0xEA, 0xF2, 0xEA);
    L.opacity = 255;

    var R = need(bgL, "splitR", null, 1200, 1350, {});
    var rsp = R.getComponent(cc.Sprite);
    if (rsp && !rsp.spriteFrame) rsp.spriteFrame = baseSF;
    R.setContentSize(1200, 1350);
    R.setPosition(600, 0);
    R.color = new cc.Color(0xF8, 0xE9, 0xE3);
    R.opacity = 255;

    /* ---------- 2. 中轴细线 ---------- */
    var mid = bgL.getChildByName("mid");
    if (!mid || !mid.isValid) {
      mid = new cc.Node("mid");
      var g = mid.addComponent(cc.Graphics);
      g.lineWidth = 2;
      g.strokeColor = new cc.Color(0xCF, 0xC7, 0xB0, 120);
      g.moveTo(0, 400);
      g.lineTo(0, -560);
      g.stroke();
      mid.parent = bgL;
      T.made++;
    }

    /* ---------- 3. 角色背后的日轮 ---------- */
    var p1 = cc.find("Canvas/ChooseView/Center/player1/player1");
    var p2 = cc.find("Canvas/ChooseView/Center/player2/player2");
    if (p1) {
      var g1 = p1.getChildByName("__chGlow");
      if (!g1 || !g1.isValid) {
        g1 = mk(p1, "__chGlow", "ch_glow", 680, 680, { color: [0x3E, 0x6E, 0x8E], opacity: 52 });
        var sh = p1.getChildByName("Shadow");
        var si = sh ? p1.children.indexOf(sh) : 0;
        g1.setSiblingIndex(si >= 0 ? si : 0);
      }
      setS(g1, 280, 280);
      place(g1, 212, 240);
      g1.color = new cc.Color(0x3E, 0x6E, 0x8E);
      g1.opacity = 52;
    }
    if (p2) {
      var g2 = p2.getChildByName("__chGlow");
      if (!g2 || !g2.isValid) {
        g2 = mk(p2, "__chGlow", "ch_glow", 680, 680, { color: [0xC0, 0x5A, 0x4A], opacity: 52 });
        var sh2 = p2.getChildByName("Shadow");
        var si2 = sh2 ? p2.children.indexOf(sh2) : 0;
        g2.setSiblingIndex(si2 >= 0 ? si2 : 0);
      }
      setS(g2, 280, 280);
      place(g2, 748, 240);
      g2.color = new cc.Color(0xC0, 0x5A, 0x4A);
      g2.opacity = 52;
    }

    /* ---------- 4. 壱 / 弐 ---------- */
    var ichi = need(topL, "ichi", "ch_ichi", 120, 150, {});
    setS(ichi, 66, 82);
    place(ichi, 212, 124);
    ichi.opacity = 255;

    var ni = need(topL, "ni", "ch_ni", 120, 150, {});
    setS(ni, 66, 82);
    place(ni, 748, 124);
    ni.opacity = 255;

    /* ---------- 5. 择一 小牌 ---------- */
    var tag = need(topL, "tag", "ch_tag", 160, 68, {});
    setS(tag, 92, 39);
    place(tag, 480, 106);

    /* ---------- 6. 左右功能入口降级为印章小签 ---------- */
    var ui = cv.getChildByName("Center") && cv.getChildByName("Center").getChildByName("2PlayersUI");
    var l1 = ui && ui.getChildByName("Player1Lbl");
    var l2 = ui && ui.getChildByName("Player2Lbl");
    if (l1) l1.active = false;
    if (l2) l2.active = false;

    var order = ["Passive", "weaponsshopping", "skinsshopping", "ColorAllShopping"];

    function stamp(p, key, who) {
      var nm = key === "Passive" ? ("PassiveBtn" + who) : key;
      var n = p.getChildByName(nm);
      if (!n) return;
      var b = n.getChildByName("Background");
      var sp = b && b.getComponent(cc.Sprite);
      if (sp) {
        var f = frame("ch_tab");
        if (f) {
          sp.spriteFrame = f;
          sp.type = cc.Sprite.Type.SLICED;
          sp.sizeMode = cc.Sprite.SizeMode.CUSTOM;
        }
      }
      setS(n, 110, 28);
      if (b) setS(b, 110, 28);
      var icon = n.getChildByName("icon");
      if (icon) icon.active = false;
      var lb = b && b.getChildByName("label");
      if (lb) {
        setF(lb, 12);
        setS(lb, 100, 26);
        lb.setPosition(0, 0);
      }
    }

    if (p1) {
      for (var i = 0; i < order.length; i++) stamp(p1, order[i], 1);
    }
    if (p2) {
      for (var j = 0; j < order.length; j++) stamp(p2, order[j], 2);
    }

    /* ---------- 7. 图鉴 / 场地 并排 ---------- */
    function smallBtn(n, sx) {
      if (!n) return;
      var b = n.getChildByName("Background");
      var sp = b && b.getComponent(cc.Sprite);
      if (sp) {
        var f = frame("ch_tab");
        if (f) {
          sp.spriteFrame = f;
          sp.type = cc.Sprite.Type.SLICED;
          sp.sizeMode = cc.Sprite.SizeMode.CUSTOM;
        }
      }
      setS(n, 100, 42);
      if (b) setS(b, 100, 42);
      place(n, sx, 362);
      var lc = b && b.getChildByName("label");
      if (lc) {
        setF(lc, 14);
        setS(lc, 92, 40);
        place(lc, sx, 362);
      }
      var ic = n.getChildByName("icon");
      if (ic) ic.active = false;
    }
    if (ui) {
      smallBtn(ui.getChildByName("r23Codex"), 424);
      smallBtn(ui.getChildByName("r23Field"), 536);
    }

    /* ---------- 8. FIGHT 长条 ---------- */
    var sb = ui && ui.getChildByName("StartBtn");
    if (sb) {
      var ssp = sb.getComponent(cc.Sprite);
      var ff = frame("ch_fight");
      if (ssp && ff) {
        ssp.spriteFrame = ff;
        ssp.sizeMode = cc.Sprite.SizeMode.CUSTOM;
        ssp.type = cc.Sprite.Type.SIMPLE;
      }
      setS(sb, 240, 76);
      place(sb, 480, 440);
      var fl = sb.getChildByName("label");
      if (fl) fl.active = false;
    }

    /* ---------- 9. 底部武器名与随机格 ---------- */
    function foot(p, nameX, cellX) {
      var wn = p.getChildByName("WeaponsName");
      var wbg = wn && wn.getChildByName("bg");
      if (wbg) wbg.active = false;
      var nmn = wn && wn.getChildByName("name");
      if (nmn) {
        setF(nmn, 16);
        nmn.color = new cc.Color(0x2E, 0x3A, 0x34);
        setS(nmn, 160, 22);
        place(nmn, nameX, 400);
      }
      var wp = p.getChildByName("Weapon");
      if (wp) {
        setS(wp, 70, 70);
        place(wp, cellX, 430);
        var rnd = wp.getChildByName("random");
        if (rnd) rnd.scale = 0.78;
      }
    }
    if (p1) foot(p1, 212, 60);
    if (p2) foot(p2, 748, 900);
  }

  function tick() {
    if (!window.cc || !cc.director) return;
    var cv = cc.find("Canvas/ChooseView");
    if (!cv) { T.built = 0; CV = null; return; }
    if (!cv.activeInHierarchy) { T.built = 0; return; }
    if (!T.ready) return;
    var now = Date.now();
    if (T.built && CV === cv && now - last < 1200) return;
    try {
      build(cv);
      CV = cv;
      last = now;
      T.built = 1;
      T.err = "";
    } catch (e) {
      T.err = String((e && e.message) || e);
      T.built = 0;
    }
  }

  setInterval(tick, 220);
})();
